/* Digitized boundaries remain estimates, not surveyed cadastral geometry. */
let parcelMapEditor=null,parcelSearchAt=0;
function openParcelMap(options={}){
 const d=parcelDraft(),geometry=options.geometry||d.mapGeometry,anchor=simplePoint(),geo=geometry?.valid?ParcelGeometry.geographic(geometry,anchor):null;
 const initial=geo?.length?[geo.reduce((s,p)=>s+p[1],0)/geo.length,geo.reduce((s,p)=>s+p[0],0)/geo.length]:anchor?[anchor.lat,anchor.lng]:[-7.115,-34.86];
 const preview=!!options.preview,approximate=!!geo&&!geometry.georeferenced;
 modal(preview?'Veja o formato no mapa.':'Desenhe os limites do terreno.',`<div class="parcel-map-body"><p class="picker-instructions" id="parcel-map-instructions">${preview?(approximate?'Posição aproximada: o desenho foi centralizado no ponto marcado, com orientação ilustrativa.':'Perímetro nas coordenadas informadas. Confira sua posição na imagem.'):'Toque para criar vértices. Feche no primeiro ponto ou pelo botão; arraste os vértices para ajustar.'}</p><form id="parcel-map-search" class="parcel-map-search"><label class="sr-only" for="parcel-map-query">Endereço ou coordenadas do terreno</label><input id="parcel-map-query" placeholder="Endereço ou latitude, longitude" autocomplete="off"><button class="btn" type="submit">${icon('search')}Buscar</button></form><div id="parcel-map-search-results" class="parcel-map-search-results" role="status"></div><div class="parcel-map-toolbar"><div role="group" aria-label="Base do mapa"><button data-parcel-map="aerial" aria-pressed="true">${icon('layers')}Aérea</button><button data-parcel-map="streets" aria-pressed="false">${icon('map')}Ruas</button></div>${!preview?'<button class="btn" data-parcel-map="add-center">Adicionar ponto no centro</button>':''}</div><div class="parcel-map-stage"><div id="parcel-boundary-map" role="region" aria-label="Mapa para desenhar o perímetro do terreno" aria-describedby="parcel-map-instructions" tabindex="0"></div><div class="parcel-map-reticle" aria-hidden="true">+</div></div><section class="parcel-map-review"><div class="parcel-map-metrics"><span>Área <strong id="parcel-map-area">—</strong></span><span>Perímetro <strong id="parcel-map-perimeter">—</strong></span><span id="parcel-map-count"></span></div><p id="parcel-map-status" role="status"></p>${preview?`<p class="parcel-map-estimate">${approximate?'A posição desenhada não identifica os limites reais do imóvel.':'Perímetro informado; sem homologação cadastral.'}</p>`:`<div class="parcel-map-edit-tools"><select id="parcel-map-selected" aria-label="Vértice selecionado"></select><button class="btn" data-parcel-map="insert">Inserir após</button><button class="btn" data-parcel-map="delete">Excluir vértice</button><button class="btn" data-parcel-map="close">Fechar perímetro</button></div><details class="parcel-map-fine"><summary>Ajustar coordenadas do vértice selecionado</summary><div><label>Latitude<input id="parcel-map-lat" inputmode="decimal"></label><label>Longitude<input id="parcel-map-lng" inputmode="decimal"></label><button class="btn" data-parcel-map="apply-coordinates">Aplicar</button></div></details><p class="parcel-map-estimate">Digitalização sobre imagem de 2021: área e limites estimados. Endereços: OpenStreetMap / Photon.</p>`}</section></div>`,`<button class="btn" data-action="close-modal">${preview?'Voltar ao esquema':'Cancelar'}</button>${preview?'':'<button class="btn primary" data-parcel-map="accept" id="parcel-map-accept" disabled>Usar este perímetro</button>'}`,true);
 $('.modal').classList.add('location-picker-modal','parcel-map-modal');$('.modal-backdrop').classList.add('location-picker-backdrop');
 const map=L.map('parcel-boundary-map',{zoomControl:false,scrollWheelZoom:false,maxBounds:locationMapConfig.bounds,maxBoundsViscosity:1,minZoom:13,maxZoom:20,fadeAnimation:false,zoomAnimation:false,inertia:false}).setView(initial,18);
 L.control.zoom({position:'topright',zoomInTitle:'Aproximar perímetro',zoomOutTitle:'Afastar perímetro'}).addTo(map);map.attributionControl.setPrefix('<a href="https://leafletjs.com" target="_blank" rel="noopener noreferrer">Leaflet</a>');L.control.scale({imperial:false,maxWidth:70}).addTo(map);
 const p=parcelMapEditor={map,preview,approximate,vertices:geo?geo.map(v=>[...v]):[],closed:!!geo,selected:0,markers:[],loaded:new Set(),failed:new Set(),polygons:L.layerGroup().addTo(map),base:null,layer:null,searchResults:[]};
 if(geo?.length)map.fitBounds(geo.map(([lng,lat])=>[lat,lng]),{padding:[45,45],maxZoom:19});
 setParcelMapBase('aerial');drawParcelBoundary();
 map.on('click',e=>{if(p.preview)return;if(p.closed){notify('Use “Inserir após” para acrescentar um vértice ao perímetro fechado.');return}if(!parcelMapImageReady()){notify('Aguarde a imagem carregar neste ponto ou alterne para Ruas.');return}addParcelMapPoint(e.latlng)});
 map.on('moveend zoomend',updateParcelMapStatus);
 p.observer=new ResizeObserver(()=>{const center=map.getCenter(),zoom=map.getZoom();map.invalidateSize({pan:false});map.setView(center,zoom,{animate:false})});p.observer.observe($('.parcel-map-stage'));map.invalidateSize({pan:false});if(options.query){$('#parcel-map-query').value=options.query;searchParcelMap(options.query)}
}
function setParcelMapBase(id){const p=parcelMapEditor;if(!p||p.base===id)return;if(p.layer)p.map.removeLayer(p.layer);p.base=id;p.loaded.clear();p.failed.clear();const c=locationMapConfig.basemaps[id],opts={minZoom:13,maxZoom:20,maxNativeZoom:id==='streets'?19:20,keepBuffer:1,updateWhenIdle:true,attribution:c.attribution};const layer=p.layer=id==='aerial'?L.tileLayer.wms(c.url,{...opts,layers:c.layer,version:'1.1.1',format:'image/jpeg',transparent:false,bounds:c.bounds}):L.tileLayer(c.url,opts);const key=c=>`${c.z}/${c.x}/${c.y}`;layer.on('tileload',e=>{if(parcelMapEditor!==p||p.layer!==layer)return;p.loaded.add(key(e.coords));p.failed.delete(key(e.coords));updateParcelMapStatus()});layer.on('tileerror',e=>{if(parcelMapEditor!==p||p.layer!==layer)return;p.failed.add(key(e.coords));updateParcelMapStatus()});layer.addTo(p.map);$$('[data-parcel-map="aerial"],[data-parcel-map="streets"]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.parcelMap===id)));updateParcelMapStatus()}
function parcelMapImageReady(){const p=parcelMapEditor;if(!p)return false;const z=Math.min(p.map.getZoom(),p.base==='streets'?19:20),c=p.map.project(p.map.getCenter(),z).divideBy(256).floor();return p.loaded.has(`${z}/${c.x}/${c.y}`)}
function parcelMapGeometry(){const p=parcelMapEditor;if(!p)return {valid:false};if(!p.closed)return {valid:false,error:'Perímetro aberto. Adicione ao menos três vértices e feche o polígono.'};return ParcelGeometry.fromGeographic(p.vertices,{kind:'map',closed:true,front:Math.min(parcelDraft().front||0,p.vertices.length-1),back:null,source:'Digitalização sobre mapa'})}
function updateParcelMapStatus(){const p=parcelMapEditor;if(!p||!$('#parcel-map-status'))return;const g=parcelMapGeometry(),ready=parcelMapImageReady();$('#parcel-map-area').textContent=g.valid?number(g.area,2)+' m²':'—';$('#parcel-map-perimeter').textContent=g.valid?number(g.perimeter,2)+' m':'—';$('#parcel-map-count').textContent=p.vertices.length+' vértices';$('#parcel-map-status').textContent=!ready?'Imagem indisponível ou carregando. Se necessário, alterne para Ruas.':g.valid?'Perímetro fechado. Revise os vértices antes de usar.':g.error;if($('#parcel-map-accept'))$('#parcel-map-accept').disabled=!g.valid;$$('[data-parcel-map="delete"],[data-parcel-map="insert"],[data-parcel-map="apply-coordinates"]').forEach(b=>b.disabled=!p.vertices.length);if($('#parcel-map-selected')){$('#parcel-map-selected').innerHTML=p.vertices.map((_,i)=>`<option value="${i}" ${i===p.selected?'selected':''}>Vértice ${i+1}</option>`).join('');const v=p.vertices[p.selected];$('#parcel-map-lat').value=v?String(v[1]):'';$('#parcel-map-lng').value=v?String(v[0]):''}}
function drawParcelBoundary(){const p=parcelMapEditor;if(!p)return;p.polygons.clearLayers();const latlngs=p.vertices.map(([lng,lat])=>[lat,lng]);if(latlngs.length>1){const options={color:'#0F2D4A',weight:3,fillColor:'#10B981',fillOpacity:.25,interactive:false,dashArray:p.approximate?'6 5':null};(p.closed?L.polygon(latlngs,options):L.polyline(latlngs,options)).addTo(p.polygons)}p.markers=[];p.vertices.forEach(([lng,lat],i)=>{const marker=L.marker([lat,lng],{draggable:!p.preview,keyboard:true,title:`Vértice ${i+1}`,icon:L.divIcon({className:'parcel-vertex-marker'+(i===p.selected?' is-selected':''),html:`<span>${i+1}</span>`,iconSize:[44,44],iconAnchor:[22,22]})}).addTo(p.polygons);marker.on('click',()=>{if(p.preview)return;p.selected=i;if(i===0&&p.vertices.length>=3&&!p.closed)p.closed=true;drawParcelBoundary()});marker.on('dragend',()=>{const v=marker.getLatLng();p.vertices[i]=[v.lng,v.lat];p.selected=i;p.approximate=false;drawParcelBoundary()});p.markers.push(marker)});updateParcelMapStatus()}
function addParcelMapPoint(latlng){const p=parcelMapEditor;if(!p||p.preview)return;if(p.vertices.length>=120){notify('Limite de 120 vértices.');return}if(!inDemoRegion(latlng.lat,latlng.lng)){notify('Use um ponto dentro do recorte de João Pessoa.');return}p.vertices.push([latlng.lng,latlng.lat]);p.selected=p.vertices.length-1;p.closed=false;p.approximate=false;drawParcelBoundary()}
function acceptParcelBoundary(){const p=parcelMapEditor,g=parcelMapGeometry();if(!g.valid)return;const d=parcelDraft();d.mode='map';d.advanced=true;d.mapGeometry=g;d.front=g.front;d.back=null;const lat=p.vertices.reduce((s,v)=>s+v[1],0)/p.vertices.length,lng=p.vertices.reduce((s,v)=>s+v[0],0)/p.vertices.length;state.lookupResult={status:'point',method:'map',lat,lng};state.lookupValues.latitude=String(lat);state.lookupValues.longitude=String(lng);state.lotConfirmed=false;state.lookupDirty=false;markParcelDirty();closeModal();render();$('#parcel-form').scrollIntoView({block:'start'});notify('Perímetro definido. Revise a testada principal e as medidas antes de analisar.')}
function disposeParcelMap(){const p=parcelMapEditor;if(!p)return;parcelMapEditor=null;p.abort?.abort();p.observer?.disconnect();p.map.remove()}
async function searchParcelMap(query){const p=parcelMapEditor;if(!p)return;const text=query.trim();if(!text)return;const pair=parseCoordinatePair(text);if(pair){const lat=decimalCoordinate(pair[0]),lng=decimalCoordinate(pair[1]);if(!inDemoRegion(lat,lng)){$('#parcel-map-search-results').textContent='Coordenadas fora do recorte de João Pessoa.';return}p.map.setView([lat,lng],19);$('#parcel-map-search-results').textContent='Localização encontrada pelas coordenadas.';return}if(Date.now()-parcelSearchAt<1100){$('#parcel-map-search-results').textContent='Aguarde um instante antes de uma nova busca.';return}parcelSearchAt=Date.now();p.abort?.abort();p.abort=new AbortController();$('#parcel-map-search-results').textContent='Buscando endereço em João Pessoa…';try{const url=new URL('https://photon.komoot.io/api/');url.search=new URLSearchParams({q:text,bbox:'-35,-7.3,-34.75,-7',limit:'4'});const response=await fetch(url,{signal:p.abort.signal,referrerPolicy:'strict-origin-when-cross-origin'});if(!response.ok)throw Error('search');const data=await response.json(),results=(data.features||[]).map(f=>({lat:f.geometry?.coordinates?.[1],lon:f.geometry?.coordinates?.[0],display_name:[f.properties?.name,f.properties?.street,f.properties?.housenumber,f.properties?.city,f.properties?.state].filter(Boolean).join(', ')}));if(parcelMapEditor!==p)return;p.searchResults=results.filter(r=>Number.isFinite(Number(r.lat))&&Number.isFinite(Number(r.lon))&&inDemoRegion(Number(r.lat),Number(r.lon))).filter((r,i,all)=>all.findIndex(x=>x.display_name===r.display_name)===i);$('#parcel-map-search-results').innerHTML=p.searchResults.length?p.searchResults.map((r,i)=>`<button type="button" data-parcel-search-result="${i}">${icon('pin')}${esc(r.display_name)}</button>`).join(''):'Nenhum endereço encontrado. Use coordenadas ou mova o mapa.'}catch(e){if(parcelMapEditor===p&&e.name!=='AbortError')$('#parcel-map-search-results').textContent='Busca de endereços indisponível. Use coordenadas ou mova o mapa.'}}
document.addEventListener('submit',e=>{if(e.target.id==='parcel-map-search'){e.preventDefault();searchParcelMap($('#parcel-map-query').value)}});
document.addEventListener('change',e=>{if(e.target.id==='parcel-map-selected'&&parcelMapEditor){parcelMapEditor.selected=Number(e.target.value);drawParcelBoundary()}});
document.addEventListener('click',e=>{const result=e.target.closest('[data-parcel-search-result]');if(result&&parcelMapEditor){const r=parcelMapEditor.searchResults[Number(result.dataset.parcelSearchResult)];if(r)parcelMapEditor.map.setView([Number(r.lat),Number(r.lon)],18);$('#parcel-map-search-results').textContent='Endereço localizado. Confira visualmente os limites do terreno.';return}const b=e.target.closest('[data-parcel-map]'),p=parcelMapEditor;if(!b||!p)return;const cmd=b.dataset.parcelMap;if(['aerial','streets'].includes(cmd)){setParcelMapBase(cmd);return}if(cmd==='accept'){acceptParcelBoundary();return}if(cmd==='add-center'){if(p.closed){notify('Use Inserir após para acrescentar um vértice ao polígono fechado.');return}if(parcelMapImageReady())addParcelMapPoint(p.map.getCenter());return}if(cmd==='close'){p.closed=true;drawParcelBoundary();return}if(cmd==='delete'){p.vertices.splice(p.selected,1);p.selected=Math.max(0,p.selected-1);if(p.vertices.length<3)p.closed=false;drawParcelBoundary();return}if(cmd==='insert'){if(p.vertices.length>=120)return;const a=p.vertices[p.selected],b=p.vertices[(p.selected+1)%p.vertices.length];p.vertices.splice(p.selected+1,0,[(a[0]+b[0])/2,(a[1]+b[1])/2]);p.selected++;drawParcelBoundary();return}if(cmd==='apply-coordinates'){const lat=decimalCoordinate($('#parcel-map-lat').value),lng=decimalCoordinate($('#parcel-map-lng').value);if(lat===null||lng===null||!inDemoRegion(lat,lng)){notify('Informe latitude e longitude válidas no recorte de João Pessoa.');return}p.vertices[p.selected]=[lng,lat];p.approximate=false;drawParcelBoundary()}});
